import java.io.Reader; 
import java.io.IOException; 

public class ReaderUtil { 
    public ReaderUtil() { 
    } 

    /** 
     * Dumps the contents of the {@link Reader} to a 
     * String, closing the {@link Reader} when done. 
     */ 
    public String readToString(Reader in) throws IOException { 
        StringBuffer buf = new StringBuffer(); 
        try { 
            for(int c = in.read(); c != -1; c = in.read()) { 
                buf.append((char)c); 
            } 
            return buf.toString(); 
        } catch(IOException e) { 
            throw e; 
        } finally { 
            try { 
                in.close(); 
            } catch(Exception e) { 
                // ignored 
            } 
        } 
    } 
}

import java.io.IOException;
import java.io.Reader;
import org.apache.commons.pool3.ObjectPool;

public class ReaderUtil {

    private ObjectPool<StringBuffer> pool;

    public ReaderUtil(ObjectPool<StringBuffer> pool) {
        this.pool = pool;
    }

    /**
     * Dumps the contents of the {@link Reader} to a String, closing the {@link Reader} when done.
     */
    public String readToString(Reader in)
        throws IOException {
        StringBuffer buf = null;
        try {
            buf = pool.borrowObject();
            for (int c = in.read(); c != -1; c = in.read()) {
                buf.append((char) c);
            }
            return buf.toString();
        } catch (IOException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Unable to borrow buffer from pool" + e.toString());
        } finally {
            try {
                in.close();
            } catch (Exception e) {
                // ignored
            }
            try {
                if (null != buf) {
                    pool.returnObject(buf);
                }
            } catch (Exception e) {
                // ignored
            }
        }
    }
}

import org.apache.commons.pool3.BasePooledObjectFactory;
import org.apache.commons.pool3.PooledObject;
import org.apache.commons.pool3.impl.DefaultPooledObject;

public class StringBufferFactory
    extends BasePooledObjectFactory<StringBuffer> {

    @Override
    public StringBuffer create() {
        return new StringBuffer();
    }

    /**
     * Use the default PooledObject implementation.
     */
    @Override
    public PooledObject<StringBuffer> wrap(StringBuffer buffer) {
        return new DefaultPooledObject<StringBuffer>(buffer);
    }

    /**
     * When an object is returned to the pool, clear the buffer.
     */
    @Override
    public void passivateObject(PooledObject<StringBuffer> pooledObject) {
        pooledObject.getObject().setLength(0);
    }

    // for all other methods, the no-op implementation
    // in BasePooledObjectFactory will suffice
}

import org.apache.commons.pool3.BaseKeyedPooledObjectFactory;
import org.apache.commons.pool3.PooledObject;
import org.apache.commons.pool3.impl.DefaultPooledObject;

public class Factory
        extends BaseKeyedPooledObjectFactory<String, StringBuilder, RuntimeException> {

    @Override
    public StringBuilder create(String key) {
        int capacity;
        switch (key) {
            case "SMALL":
                capacity = 64;
                break;
            case "MEDIUM":
                capacity = 256;
                break;
            case "LARGE":
                capacity = 1024;
                break;
            default:
                capacity = 128;
        }
        return new StringBuilder(capacity);
    }

    @Override
    public PooledObject<StringBuilder> wrap(StringBuilder value) {
        return new DefaultPooledObject<>(value);
    }

    @Override
    public void passivateObject(String key, PooledObject<StringBuilder> p) {
        p.getObject().setLength(0);
    }
}

import org.apache.commons.pool3.KeyedObjectPool;
import org.apache.commons.pool3.impl.GenericKeyedObjectPool;

public class KeyedPoolExample {

    private KeyedObjectPool<String, StringBuilder> pool;

    public KeyedPoolExample(KeyedObjectPool<String, StringBuilder> pool) {
        this.pool = pool;
    }

    public String build(String key, String... lines) {
        StringBuilder buf = null;
        try {
            buf = pool.borrowObject(key);
            for (String line : lines) {
                buf.append(line);
            }
            return buf.toString();
        } catch (Exception e) {
            throw new RuntimeException(
                "Unable to borrow buffer for key=" + key, e);
        } finally {
            try {
                if (buf != null) {
                    pool.returnObject(key, buf);
                }
            } catch (Exception e) {
                // ignored
            }
        }
    }
}

KeyedPoolExample example = new KeyedPoolExample(
    new GenericKeyedObjectPool<>(new Factory()));
String result = example.build("MEDIUM", "Hello, ", "KeyedObjectPool!");
